const screens=[...document.querySelectorAll('.screen')],stack=[],foods=new Set();let meal='Bữa trưa',offline=false,pending=false,saved=0,remind=false,timer;
function go(id,push=true){const current=screens.find(s=>!s.hidden)?.id;if(push&&current&&current!==id)stack.push(current);screens.forEach(s=>s.hidden=s.id!==id);document.getElementById('nav').hidden=id==='s01';document.querySelectorAll('[data-nav]').forEach(b=>{const active=id===b.dataset.nav||(['s03','s04','s05'].includes(id)&&b.dataset.nav==='s02')||(id==='s08'&&b.dataset.nav==='s07');b.setAttribute('aria-current',active?'page':'false')});if(id==='s05'){review();document.getElementById('saveResult').hidden=true;document.getElementById('saveActions').hidden=false;}if(id==='s02')refreshHome();document.getElementById('wrap').scrollTop=0}
function back(){go(stack.pop()||'s02',false)}
function singleChip(b){b.parentElement.querySelectorAll('.chip').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}
function pickMeal(b,v){meal=v;document.querySelectorAll('#s03 .choice').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}
function toggleFood(b,v){if(foods.has(v))foods.delete(v);else foods.add(v);b.setAttribute('aria-pressed',String(foods.has(v)))}
function updateCount(){document.getElementById('chars').textContent=document.getElementById('mealnote').value.length}
function review(){document.getElementById('rmeal').textContent=meal;document.getElementById('rfood').textContent=foods.size?[...foods].join(', '):'Chưa chọn';document.getElementById('rnote').textContent=document.getElementById('mealnote').value.trim()||'Không có'}
function refreshHome(){document.getElementById('sync').hidden=!pending;document.getElementById('count').textContent=(3+saved)+' lần ghi nhận';document.getElementById('weekcount').textContent=String(3+saved);document.getElementById('progressbar').style.width=Math.min(45+saved*10,95)+'%';document.getElementById('todaySummary').textContent=saved?saved+' bản ghi đã lưu trên thiết bị.':'Chưa có bản ghi. Bạn có thể ghi khi thuận tiện.'}
function saveMeal(forceOffline){const b=document.getElementById('savebtn');b.disabled=true;b.textContent='Đang lưu…';setTimeout(()=>{b.disabled=false;b.textContent='Lưu bản ghi';saved++;const wait=forceOffline||offline;pending=wait;offline=wait;document.getElementById('saveActions').hidden=true;document.getElementById('saveResult').hidden=false;document.getElementById('saveState').textContent=wait?'Đã lưu trên thiết bị':'Đã lưu và đồng bộ';document.getElementById('saveCopy').textContent=wait?'Bản ghi đang chờ mạng. Bạn có thể thử đồng bộ hoặc về hôm nay.':'Bản ghi đã được lưu và đồng bộ.';document.getElementById('reviewRetry').hidden=!wait;toast(wait?'Đã lưu trên thiết bị. Bản ghi chờ đồng bộ.':'Đã lưu và đồng bộ thành công.');},650)}
function toggleOffline(){offline=!offline;document.getElementById('network').textContent=offline?'◌　Ngoại tuyến':'●●●　Wi-Fi　▰';toast(offline?'Đang mô phỏng kết nối yếu.':'Đã khôi phục kết nối trong bản thử.')}
function retrySync(){offline=false;document.getElementById('network').textContent='●●●　Wi-Fi　▰';const b=document.getElementById('retry');b.disabled=true;b.textContent='Đang thử…';toast('Đang đồng bộ bản ghi…');setTimeout(()=>{pending=false;b.disabled=false;b.textContent='Đã đồng bộ';document.getElementById('saveState').textContent='Đã đồng bộ thành công';document.getElementById('saveCopy').textContent='Bản ghi đã được đồng bộ.';document.getElementById('reviewRetry').hidden=true;refreshHome();toast('Đã đồng bộ thành công.')},900)}
function saveGoal(){const g=document.querySelector('input[name=goal]:checked');document.getElementById('homegoal').textContent=g?g.value:'Tự chọn sau';toast('Đã lưu lựa chọn. Bạn có thể đổi bất cứ lúc nào.');go('s02')}
function toggleReminder(){remind=!remind;document.getElementById('toggle').setAttribute('aria-pressed',String(remind));document.getElementById('toggle').textContent=remind?'Bật　●':'Tắt　○';document.getElementById('reminders').hidden=!remind}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.hidden=false;clearTimeout(timer);timer=setTimeout(()=>t.hidden=true,2800)}
function openPrivacy(){document.getElementById('modal').hidden=false}
function closePrivacy(){document.getElementById('modal').hidden=true}
function openLesson(topic=''){const d={'':['Đậu trong bữa ăn quen thuộc','🫘'],'rau':['Thêm rau theo cách vừa túi tiền','🥬'],'grain':['Hiểu về ngũ cốc nguyên hạt','🌾']}[topic];document.getElementById('lessonTitle').textContent=d[0];document.getElementById('lessonEmoji').textContent=d[1];go('s08')}
function filterLessons(){const q=document.getElementById('search').value.toLocaleLowerCase('vi');document.querySelectorAll('#lessons .lesson').forEach(x=>x.hidden=!x.textContent.toLocaleLowerCase('vi').includes(q))}

function confirmCancel(){document.getElementById('cancelModal').hidden=false}
function closeCancel(){document.getElementById('cancelModal').hidden=true}
function discardDraft(){closeCancel();foods.clear();document.querySelectorAll('.food').forEach(b=>b.setAttribute('aria-pressed','false'));document.getElementById('mealnote').value='';updateCount();meal='Bữa trưa';toast('Bản nháp đã được hủy.');go('s02')}
